(() => {
    "use strict";

    /**
     * @typedef {Object} ScoringOption
     * @property {string} identifier - Unique identifier for the scoring option.
     * @property {boolean} correct - Whether this option is considered correct.
     *
     * TODO: Generated by ChatGPT. Review and replace with your project's
     * canonical type definition if one exists.
     */

    /**
     * @typedef {Object} QuestionScoring
     * @property {ScoringOption[]} [options] - Available scored options.
     * @property {number} [accepted_value] - Accepted numeric answer.
     * @property {number} [tolerance] - Permitted numeric deviation.
     * @property {string[]} [accepted_answers] - Accepted textual answers.
     *
     * TODO: Generated by ChatGPT. Review the optional fields against the actual
     * assessment schema before treating this as authoritative.
     */

    /**
     * @typedef {Object} AssessmentQuestion
     * @property {string} identifier - Unique question identifier.
     * @property {string} type - Question type.
     * @property {QuestionScoring} scoring - Scoring configuration.
     * @property {string} feedback_correct - Feedback shown for a correct answer.
     * @property {string} feedback_incorrect - Feedback shown for an incorrect answer.
     *
     * TODO: Generated by ChatGPT. Replace the broad string question type with a
     * union typedef if the schema is stable.
     */

    /**
     * @typedef {Object} AssessmentAttempt
     * @property {number} score - Assessment score expressed as a fraction.
     * @property {string} attemptedAt - ISO 8601 timestamp for the attempt.
     *
     * TODO: Generated by ChatGPT. Verify against the educationProgress storage schema.
     */

    /**
     * @typedef {Object} EducationProgress
     * @property {Object.<string, AssessmentAttempt[]>} attempts - Attempts grouped by assessment identifier.
     * @property {string[]} missedConcepts - Concepts that the learner has missed.
     *
     * TODO: Generated by ChatGPT. Verify against the actual persisted progress structure.
     */

    /**
     * @typedef {Object} EducationProgressApi
     * @property {function(): Promise<EducationProgress>} readProgress - Reads saved progress.
     * @property {function(EducationProgress): Promise<void>} writeProgress - Writes saved progress.
     *
     * TODO: Generated by ChatGPT. Replace with the project's actual API contract if available.
     */

    /**
     * Assessment form associated with the current page.
     *
     * @type {HTMLFormElement|null}
     */
    const form = document.querySelector("form[data-assessment-id]");

    /*
     * Stop initialization when this page does not contain an assessment form.
     */
    if (!form) {
        return;
    }

    /**
     * Script element containing serialized assessment data.
     *
     * @type {HTMLElement|null}
     */
    const assessmentDataElement = document.getElementById("assessment-data");

    /*
     * The original implementation assumes this element exists.
     * Preserve that expectation rather than silently changing behavior.
     */

    /**
     * Parsed assessment questions.
     *
     * @type {AssessmentQuestion[]}
     */
    const questions = JSON.parse(assessmentDataElement.textContent);

    /**
     * Return the currently selected values for a question.
     *
     * Values are sorted so comparisons are independent of DOM/input ordering.
     *
     * TODO: Generated by ChatGPT. Review selector escaping and return semantics
     * before copying into production unchanged.
     *
     * @param {AssessmentQuestion} question - Question whose checked values should be read.
     * @returns {string[]} Sorted selected answer identifiers.
     */
    function selectedValues(question) {
        /**
         * Checked inputs belonging to the question.
         *
         * @type {NodeListOf<HTMLInputElement>}
         */
        const selectedInputs = form.querySelectorAll(
            `[name="${CSS.escape(question.identifier)}"]:checked`,
        );

        return [...selectedInputs]
            .map(
                /**
                 * Extract an input's submitted value.
                 *
                 * TODO: Generated by ChatGPT. This callback exists primarily for
                 * readability and explicit typing.
                 *
                 * @param {HTMLInputElement} input - Selected form input.
                 * @returns {string} Input value.
                 */
                (input) => input.value,
            )
            .sort();
    }

    /**
     * Determine whether the user's current answer to a question is correct.
     *
     * TODO: Generated by ChatGPT. Verify scoring assumptions against the
     * authoritative assessment schema before relying on this implementation.
     *
     * @param {AssessmentQuestion} question - Question to score.
     * @returns {boolean} True when the submitted answer is correct.
     */
    function isCorrect(question) {
        /**
         * Scoring configuration for the current question.
         *
         * @type {QuestionScoring}
         */
        const scoring = question.scoring;

        /**
         * Question types that are scored by comparing selected option identifiers.
         *
         * @type {string[]}
         */
        const optionBasedQuestionTypes = [
            "single_choice",
            "multiple_select",
            "true_false",
        ];

        if (optionBasedQuestionTypes.includes(question.type)) {
            /**
             * Expected option identifiers, sorted for order-independent comparison.
             *
             * @type {string[]}
             */
            const expected = scoring.options
                .filter(
                    /**
                     * Return whether an option is marked correct.
                     *
                     * TODO: Generated by ChatGPT. Review before copying.
                     *
                     * @param {ScoringOption} option - Scoring option.
                     * @returns {boolean} Whether the option is correct.
                     */
                    (option) => option.correct,
                )
                .map(
                    /**
                     * Extract an option's identifier.
                     *
                     * TODO: Generated by ChatGPT. Review before copying.
                     *
                     * @param {ScoringOption} option - Scoring option.
                     * @returns {string} Option identifier.
                     */
                    (option) => option.identifier,
                )
                .sort();

            return (
                JSON.stringify(selectedValues(question))
                === JSON.stringify(expected)
            );
        }

        /**
         * Form control associated with the question identifier.
         *
         * @type {RadioNodeList|Element|null}
         */
        const input = form.elements.namedItem(question.identifier);

        if (question.type === "numeric") {
            return (
                Math.abs(Number(input.value) - scoring.accepted_value)
                <= scoring.tolerance
            );
        }

        /**
         * Normalize textual answers before comparison.
         *
         * Normalization trims surrounding whitespace, lowercases the text using
         * locale-aware rules, and collapses repeated internal whitespace.
         *
         * TODO: Generated by ChatGPT. Confirm locale-aware lowercase behavior is
         * desired for your assessment content.
         *
         * @param {string} value - Raw answer text.
         * @returns {string} Normalized answer text.
         */
        const normalization = (value) => (
            value
                .trim()
                .toLocaleLowerCase()
                .replace(/\s+/g, " ")
        );

        return scoring.accepted_answers
            .map(normalization)
            .includes(normalization(input.value));
    }

    /**
     * Handle assessment form submission.
     *
     * The handler scores every question, updates visible feedback, displays the
     * aggregate score, and persists progress when the educationProgress API exists.
     *
     * TODO: Generated by ChatGPT. Review the persistence schema and null assumptions
     * before copying into production unchanged.
     *
     * @param {SubmitEvent} event - Form submission event.
     * @returns {Promise<void>}
     */
    async function handleSubmit(event) {
        event.preventDefault();

        /**
         * Number of correctly answered questions.
         *
         * @type {number}
         */
        let correctCount = 0;

        /**
         * Concepts missed during this assessment.
         *
         * @type {string[]}
         */
        const missedConcepts = [];

        questions.forEach(
            /**
             * Score a single question and update its feedback element.
             *
             * TODO: Generated by ChatGPT. Consider extracting this into a named
             * function if question rendering becomes more complicated.
             *
             * @param {AssessmentQuestion} question - Question being scored.
             * @returns {void}
             */
            (question) => {
                /**
                 * Whether the current answer is correct.
                 *
                 * @type {boolean}
                 */
                const correct = isCorrect(question);

                if (correct) {
                    correctCount += 1;
                }

                /**
                 * Feedback container associated with the current question.
                 *
                 * @type {HTMLElement|null}
                 */
                const feedback = form.querySelector(
                    `[data-question-id="${CSS.escape(question.identifier)}"] `
                    + "[data-feedback]",
                );

                feedback.textContent = correct
                    ? question.feedback_correct
                    : `${question.feedback_incorrect} Review the linked lesson.`;

                if (correct) {
                    feedback.classList.remove("incorrect-answer");
                    feedback.classList.add("correct-answer");
                } else {
                    feedback.classList.remove("correct-answer");
                    feedback.classList.add("incorrect-answer");
                }
            },
        );

        /**
         * Fractional assessment score in the range 0 through 1.
         *
         * @type {number}
         */
        const score = questions.length
            ? correctCount / questions.length
            : 0;

        /**
         * Element displaying the final assessment score.
         *
         * @type {HTMLElement|null}
         */
        const scoreElement = form.querySelector("[data-score]");

        scoreElement.textContent = (
            `Score: ${correctCount} of ${questions.length} `
            + `(${Math.round(score * 100)}%).`
        );

        /**
         * Container containing navigation or continuation controls.
         *
         * @type {HTMLElement|null}
         */
        const nextContainer = form.querySelector("[data-next-container]");

        nextContainer.hidden = false;

        /*
         * Persist the attempt only when the optional progress API is available.
         */
        if (window.educationProgress) {
            /**
             * Persisted education progress.
             *
             * @type {EducationProgress}
             */
            const progress = await window.educationProgress.readProgress();

            /**
             * Current assessment identifier.
             *
             * @type {string}
             */
            const identifier = form.dataset.assessmentId;

            /**
             * Previous attempts for the current assessment.
             *
             * @type {AssessmentAttempt[]}
             */
            const previousAttempts = progress.attempts[identifier] || [];

            progress.attempts[identifier] = [
                ...previousAttempts,
                {
                    score,
                    attemptedAt: new Date().toISOString(),
                },
            ];

            progress.missedConcepts = [
                ...new Set([
                    ...progress.missedConcepts,
                    ...missedConcepts,
                ]),
            ];

            await window.educationProgress.writeProgress(progress);
        }
    }

    form.addEventListener("submit", handleSubmit);

    /**
     * Timer display element.
     *
     * @type {HTMLElement|null}
     */
    const timer = document.querySelector("[data-timer]");

    /**
     * Checkbox used to disable the assessment timer.
     *
     * @type {HTMLInputElement|null}
     */
    const disableTimer = document.querySelector("[data-disable-timer]");

    if (timer) {
        /**
         * Configured assessment duration in seconds.
         *
         * @type {number}
         */
        const configuredSeconds = Number(form.dataset.timeLimit);

        /**
         * Remaining timer duration in seconds.
         *
         * @type {number}
         */
        let remaining = configuredSeconds;

        /**
         * Update the assessment timer display.
         *
         * TODO: Generated by ChatGPT. Review interval lifecycle behavior if the
         * assessment can be dynamically removed from the page.
         *
         * @returns {void}
         */
        function updateTimer() {
            if (disableTimer?.checked || remaining <= 0) {
                timer.textContent = disableTimer?.checked
                    ? "Timer disabled."
                    : "Time elapsed; you may still finish.";

                return;
            }

            remaining -= 1;
            timer.textContent = `${remaining} seconds remaining`;
        }

        window.setInterval(updateTimer, 1000);
    }
})();

